input.content:
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const starCountEl = document.getElementById('starCount');
const mountNameEl = document.getElementById('mountName');
const screenMessage = document.getElementById('screenMessage');
const screenTitle = document.getElementById('screenTitle');
const screenText = document.getElementById('screenText');

const world = {
  width: 1200,
  height: 760,
};

const keys = new Set();
const touchButtons = document.querySelectorAll('[data-key]');

for (const button of touchButtons) {
  const key = button.dataset.key;
  const setKey = (active) => {
    if (active) keys.add(key);
    else keys.delete(key);
  };

  button.addEventListener('pointerdown', (e) => {
    e.preventDefault();
    setKey(true);
  });
  button.addEventListener('pointerup', () => setKey(false));
  button.addEventListener('pointerleave', () => setKey(false));
  button.addEventListener('pointercancel', () => setKey(false));
}

window.addEventListener('keydown', (event) => {
  if (event.code === 'KeyE') {
    event.preventDefault();
    swapMount();
  }
  keys.add(event.code);
});

window.addEventListener('keyup', (event) => {
  keys.delete(event.code);
});

const state = {
  time: 0,
  stars: 0,
  totalStars: 6,
  win: false,
  phase: 'intro',
  mounted: 'Koraidon',
  mountIndex: 0,
  campfire: { x: 1050, y: 640, r: 48 },
  player: {
    x: 180,
    y: 520,
    vx: 0,
    vy: 0,
    radius: 20,
    speed: 240,
  },
  starsList: [
    { x: 210, y: 160, r: 12 },
    { x: 332, y: 315, r: 12 },
    { x: 520, y: 198, r: 12 },
    { x: 660, y: 390, r: 12 },
    { x: 840, y: 220, r: 12 },
    { x: 975, y: 120, r: 12 },
  ],
  obstacles: [
    { x: 260, y: 460, w: 120, h: 170 },
    { x: 432, y: 335, w: 180, h: 140 },
    { x: 615, y: 500, w: 190, h: 140 },
    { x: 845, y: 360, w: 210, h: 160 },
  ],
};

const mounts = [
  { name: 'Koraidon', color: '#dc8a45', accent: '#f7c672', trail: 'rgba(255, 194, 103, 0.45)' },
  { name: 'Miraidon', color: '#6fb7d5', accent: '#d5f5ff', trail: 'rgba(139, 211, 255, 0.38)' },
];

function swapMount() {
  if (state.phase === 'ended') return;
  state.mountIndex = (state.mountIndex + 1) % mounts.length;
  state.mounted = mounts[state.mountIndex].name;
  mountNameEl.textContent = state.mounted;
}

function setMessage(title, text, visible = true) {
  screenTitle.textContent = title;
  screenText.textContent = text;
  screenMessage.classList.toggle('visible', visible);
}

function resetGame() {
  state.stars = 0;
  state.win = false;
  state.phase = 'playing';
  state.player.x = 180;
  state.player.y = 520;
  state.player.vx = 0;
  state.player.vy = 0;
  state.mountIndex = 0;
  state.mounted = mounts[0].name;
  starCountEl.textContent = `0 / ${state.totalStars}`;
  mountNameEl.textContent = state.mounted;
  setMessage('Welcome to the Frontier', 'Ride through the canyon, gather the legendary sparks, and return to camp before sundown.', false);
}

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function rectCircleCollide(rect, circle) {
  const closestX = clamp(circle.x, rect.x, rect.x + rect.w);
  const closestY = clamp(circle.y, rect.y, rect.y + rect.h);
  const dx = circle.x - closestX;
  const dy = circle.y - closestY;
  return dx * dx + dy * dy < circle.radius * circle.radius;
}

function update(dt) {
  if (state.phase === 'intro') {
    state.time += dt;
    if (state.time > 2.2) {
      resetGame();
    }
    return;
  }

  if (state.phase === 'ended') return;

  const moveX = (keys.has('ArrowRight') || keys.has('KeyD') ? 1 : 0) - (keys.has('ArrowLeft') || keys.has('KeyA') ? 1 : 0);
  const moveY = (keys.has('ArrowDown') || keys.has('KeyS') ? 1 : 0) - (keys.has('ArrowUp') || keys.has('KeyW') ? 1 : 0);

  const length = Math.hypot(moveX, moveY) || 1;
  const vx = (moveX / length) * state.player.speed;
  const vy = (moveY / length) * state.player.speed;

  let nextX = state.player.x + vx * dt;
  let nextY = state.player.y + vy * dt;

  const radius = state.player.radius;

  for (const obstacle of state.obstacles) {
    const hit = rectCircleCollide(obstacle, { x: nextX, y: nextY, radius });
    if (hit) {
      const prevX = state.player.x;
      const prevY = state.player.y;
      const candidateX = state.player.x + vx * dt;
      const candidateY = state.player.y + vy * dt;
      const safeX = rectCircleCollide(obstacle, { x: candidateX, y: prevY, radius }) ? state.player.x : candidateX;
      const safeY = rectCircleCollide(obstacle, { x: prevX, y: candidateY, radius }) ? state.player.y : candidateY;
      nextX = safeX;
      nextY = safeY;
    }
  }

  state.player.x = clamp(nextX, radius + 10, world.width - radius - 10);
  state.player.y = clamp(nextY, radius + 10, world.height - radius - 10);

  for (let i = state.starsList.length - 1; i >= 0; i--) {
    const star = state.starsList[i];
    const dist = Math.hypot(state.player.x - star.x, state.player.y - star.y);
    if (dist < star.r + state.player.radius + 8) {
      state.starsList.splice(i, 1);
      state.stars += 1;
      starCountEl.textContent = `${state.stars} / ${state.totalStars}`;
      if (state.stars >= state.totalStars) {
        setMessage('The stars awaken', 'The six relic stars are blazing. Head back to the ranch campfire to finish the legend.', true);
      }
    }
  }

  const campDist = Math.hypot(state.player.x - state.campfire.x, state.player.y - state.campfire.y);
  if (campDist < 58 && state.stars >= state.totalStars && !state.win) {
    state.win = true;
    state.phase = 'ended';
    setMessage('Legend complete!', 'You brought the relic stars home and became the new champion of the Scarlet Frontier.', true);
  }

  if (campDist < 58 && state.stars < state.totalStars) {
    setMessage('Campfire ahead', 'This camp is warm but the legend is incomplete. Gather the remaining stars first.', true);
  }
}

function drawBackground() {
  const sky = ctx.createLinearGradient(0, 0, 0, world.height);
  sky.addColorStop(0, '#6a8f73');
  sky.addColorStop(0.25, '#a6c988');
  sky.addColorStop(0.58, '#d3ca8d');
  sky.addColorStop(1, '#b67d4f');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, world.width, world.height);

  ctx.fillStyle = 'rgba(19, 15, 14, 0.12)';
  for (let i = 0; i < 8; i++) {
    ctx.beginPath();
    ctx.arc(90 + i * 160, 110 + (i % 2) * 40, 36, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.fillStyle = '#6b4536';
  for (let i = 0; i < 4; i++) {
    ctx.fillRect(140 + i * 180, 410 + (i % 2) * 18, 90, 120);
  }

  ctx.fillStyle = '#5b342f';
  ctx.fillRect(0, 585, world.width, 180);
  ctx.fillStyle = '#7c4d3a';
  for (let i = 0; i < 14; i++) {
    ctx.beginPath();
    ctx.moveTo(0 + i * 90, 610);
    ctx.lineTo(60 + i * 90, 470);
    ctx.lineTo(120 + i * 90, 610);
    ctx.fill();
  }

  ctx.fillStyle = '#8b5d3c';
  ctx.fillRect(0, 635, world.width, 140);
}

function drawCampfire() {
  const { x, y, r } = state.campfire;
  ctx.fillStyle = '#1a120f';
  ctx.beginPath();
  ctx.arc(x, y + 12, r, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#f0b556';
  for (let i = 0; i < 7; i++) {
    const angle = (i / 7) * Math.PI * 2 + state.time * 1.4;
    const flameR = r * 0.55 + Math.sin(state.time * 8 + i) * 4;
    const px = x + Math.cos(angle) * flameR;
    const py = y - 10 + Math.sin(angle) * flameR;
    ctx.beginPath();
    ctx.arc(px, py, 10, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawStar(star) {
  const pulse = 1 + Math.sin(state.time * 5 + star.x) * 0.2;
  const radius = star.r * pulse;
  ctx.save();
  ctx.translate(star.x, star.y);
  ctx.fillStyle = '#f5d57a';
  ctx.shadowBlur = 18;
  ctx.shadowColor = '#f5d57a';
  ctx.beginPath();
  for (let i = 0; i < 5; i++) {
    const outerX = Math.cos((Math.PI * 2 * i) / 5 - Math.PI / 2) * radius;
    const outerY = Math.sin((Math.PI * 2 * i) / 5 - Math.PI / 2) * radius;
    const innerX = Math.cos((Math.PI * 2 * (i + 0.5)) / 5 - Math.PI / 2) * (radius * 0.45);
    const innerY = Math.sin((Math.PI * 2 * (i + 0.5)) / 5 - Math.PI / 2) * (radius * 0.45);
    if (i === 0) ctx.moveTo(outerX, outerY);
    else ctx.lineTo(outerX, outerY);
    ctx.lineTo(innerX, innerY);
  }
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawObstacles() {
  ctx.fillStyle = '#8f5d3b';
  for (const obstacle of state.obstacles) {
    ctx.fillRect(obstacle.x, obstacle.y, obstacle.w, obstacle.h);
    ctx.fillStyle = '#6b3d2c';
    ctx.fillRect(obstacle.x + 12, obstacle.y + 12, obstacle.w - 24, 10);
    ctx.fillStyle = '#8f5d3b';
  }
}

function drawPlayer() {
  const mount = mounts[state.mountIndex];
  const p = state.player;
  ctx.save();

  ctx.lineWidth = 5;
  ctx.strokeStyle = '#2a201c';
  ctx.beginPath();
  ctx.arc(p.x, p.y - 18, 20, 0, Math.PI * 2);
  ctx.stroke();

  ctx.fillStyle = mount.color;
  ctx.beginPath();
  ctx.ellipse(p.x, p.y + 18, 38, 22, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = mount.accent;
  ctx.beginPath();
  ctx.ellipse(p.x - 8, p.y - 18, 10, 12, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#fff';
  ctx.fillRect(p.x - 18, p.y - 34, 36, 12);
  ctx.fillStyle = '#2a201c';
  ctx.fillRect(p.x - 12, p.y - 34, 8, 8);
  ctx.fillRect(p.x + 4, p.y - 34, 8, 8);

  ctx.fillStyle = mount.accent;
  ctx.fillRect(p.x - 48, p.y + 20, 18, 30);
  ctx.fillRect(p.x + 30, p.y + 20, 18, 30);

  ctx.fillStyle = '#f0c76a';
  ctx.beginPath();
  ctx.arc(p.x + 70, p.y - 10, 12, 0, Math.PI * 2);
  ctx.fill();

  ctx.restore();
}

function drawHudMap() {
  ctx.strokeStyle = 'rgba(255, 237, 175, 0.4)';
  ctx.lineWidth = 2;
  ctx.strokeRect(18, 18, 220, 120);

  ctx.fillStyle = 'rgba(255, 239, 183, 0.75)';
  ctx.fillRect(30, 80, 18, 18);
  ctx.fillStyle = '#d55a4a';
  ctx.fillRect(70, 36, 18, 18);
  ctx.fillStyle = '#c4a25c';
  ctx.fillRect(110, 76, 18, 18);

  ctx.fillStyle = 'rgba(255,243,200,0.9)';
  ctx.font = '12px "DM Mono", monospace';
  ctx.fillText('camp', 52, 94);
  ctx.fillText('star', 92, 50);
  ctx.fillText('trail', 132, 90);
}

function render() {
  drawBackground();
  drawHudMap();
  drawCampfire();
  drawObstacles();
  for (const star of state.starsList) drawStar(star);
  drawPlayer();
}

let last = 0;
function tick(timestamp) {
  const dt = Math.min((timestamp - last) / 1000 || 0.016, 0.032);
  last = timestamp;
  state.time += dt;
  update(dt);
  render();
  requestAnimationFrame(tick);
}

resetGame();
requestAnimationFrame(tick);

