131: function rectCircleCollide(rect, circle) {
132:   const closestX = clamp(circle.x, rect.x, rect.x + rect.w);
133:   const closestY = clamp(circle.y, rect.y, rect.y + rect.h);
134:   const dx = circle.x - closestX;
135:   const dy = circle.y - closestY;
136:   return dx * dx + dy * dy < circle.radius * circle.radius;
137: }
