139: function update(dt) {
140:   if (state.phase === 'intro') {
141:     state.time += dt;
142:     if (state.time > 2.2) {
143:       resetGame();
144:     }
145:     return;
146:   }
147: 
148:   if (state.phase === 'ended') return;
149: 
150:   const moveX = (keys.has('ArrowRight') || keys.has('KeyD') ? 1 : 0) - (keys.has('ArrowLeft') || keys.has('KeyA') ? 1 : 0);
151:   const moveY = (keys.has('ArrowDown') || keys.has('KeyS') ? 1 : 0) - (keys.has('ArrowUp') || keys.has('KeyW') ? 1 : 0);
152: 
153:   const length = Math.hypot(moveX, moveY) || 1;
154:   const vx = (moveX / length) * state.player.speed;
155:   const vy = (moveY / length) * state.player.speed;
156: 
157:   let nextX = state.player.x + vx * dt;
158:   let nextY = state.player.y + vy * dt;
159: 
160:   const radius = state.player.radius;
161: 
162:   for (const obstacle of state.obstacles) {
163:     const hit = rectCircleCollide(obstacle, { x: nextX, y: nextY, radius });
164:     if (hit) {
165:       const prevX = state.player.x;
166:       const prevY = state.player.y;
167:       const candidateX = state.player.x + vx * dt;
168:       const candidateY = state.player.y + vy * dt;
169:       const safeX = rectCircleCollide(obstacle, { x: candidateX, y: prevY, radius }) ? state.player.x : candidateX;
170:       const safeY = rectCircleCollide(obstacle, { x: prevX, y: candidateY, radius }) ? state.player.y : candidateY;
171:       nextX = safeX;
172:       nextY = safeY;
173:     }
174:   }
175: 
176:   state.player.x = clamp(nextX, radius + 10, world.width - radius - 10);
177:   state.player.y = clamp(nextY, radius + 10, world.height - radius - 10);
178: 
179:   for (let i = state.starsList.length - 1; i >= 0; i--) {
180:     const star = state.starsList[i];
181:     const dist = Math.hypot(state.player.x - star.x, state.player.y - star.y);
182:     if (dist < star.r + state.player.radius + 8) {
183:       state.starsList.splice(i, 1);
184:       state.stars += 1;
185:       starCountEl.textContent = `${state.stars} / ${state.totalStars}`;
186:       if (state.stars >= state.totalStars) {
187:         setMessage('Treat trail complete!', 'You found all six golden treats! Bring Bootin’ and Chewy back to the ranch campfire.', true);
188:       }
189:     }
190:   }
191: 
192:   const campDist = Math.hypot(state.player.x - state.campfire.x, state.player.y - state.campfire.y);
193:   if (campDist < 58 && state.stars >= state.totalStars && !state.win) {
194:     state.win = true;
195:     state.phase = 'ended';
196:     setMessage('Good dogs. Great legends.', 'Bootin’ and Chewy saved the ranch! Press R to run the trail again, or E to switch editions.', true);
197:   }
198: 
199:   if (campDist < 58 && state.stars < state.totalStars) {
200:     setMessage('Campfire ahead', 'This camp is warm but the legend is incomplete. Gather the remaining stars first.', true);
201:   }
202: }
