input.oldString:
function drawStar(star) {
  const pulse = 1 + Math.sin(state.time * 5 + star.x) * 0.2;
  const radius = star.r * pulse;
  ctx.save();
  ctx.translate(star.x, star.y);
  ctx.fillStyle = '#f5d57a';
  ctx.shadowBlur = 18;
  ctx.shadowColor = '#f5d57a';
  ctx.beginPath();
  for (let i = 0; i < 5; i++) {
    const outerX = Math.cos((Math.PI * 2 * i) / 5 - Math.PI / 2) * radius;
    const outerY = Math.sin((Math.PI * 2 * i) / 5 - Math.PI / 2) * radius;
    const innerX = Math.cos((Math.PI * 2 * (i + 0.5)) / 5 - Math.PI / 2) * (radius * 0.45);
    const innerY = Math.sin((Math.PI * 2 * (i + 0.5)) / 5 - Math.PI / 2) * (radius * 0.45);
    if (i === 0) ctx.moveTo(outerX, outerY);
    else ctx.lineTo(outerX, outerY);
    ctx.lineTo(innerX, innerY);
  }
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

input.newString:
function drawTreat(treat) {
  const pulse = 1 + Math.sin(state.time * 5 + treat.x) * 0.12;
  ctx.save();
  ctx.translate(treat.x, treat.y);
  ctx.rotate(Math.sin(state.time * 2 + treat.y) * 0.12);
  ctx.scale(pulse, pulse);
  ctx.fillStyle = '#ffe49a';
  ctx.shadowBlur = 18;
  ctx.shadowColor = '#ffd45f';
  ctx.lineWidth = 3;
  ctx.strokeStyle = '#a76432';
  ctx.beginPath();
  ctx.roundRect(-10, -5, 20, 10, 4);
  ctx.fill();
  ctx.stroke();
  for (const x of [-10, 10]) {
    ctx.beginPath(); ctx.arc(x, -6, 5, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    ctx.beginPath(); ctx.arc(x, 6, 5, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
  }
  ctx.fillStyle = '#fff5cb';
  ctx.beginPath(); ctx.arc(-3, -1, 2, 0, Math.PI * 2); ctx.fill();
  ctx.restore();
}

