const wait = (ms) => new Promise(resolve => setTimeout(resolve, ms));
(async () => {
  const targets = await fetch('http://127.0.0.1:9222/json').then(r => r.json());
  const target = targets.find(item => item.type === 'page');
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, { once: true }); ws.addEventListener('error', reject, { once: true }); });
  let id = 0;
  const pending = new Map();
  ws.addEventListener('message', event => {
    const message = JSON.parse(event.data);
    if (!message.id || !pending.has(message.id)) return;
    const { resolve, reject } = pending.get(message.id);
    pending.delete(message.id);
    message.error ? reject(new Error(message.error.message)) : resolve(message.result);
  });
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const commandId = ++id;
    pending.set(commandId, { resolve, reject });
    ws.send(JSON.stringify({ id: commandId, method, params }));
  });
  const evaluate = async expression => (await send('Runtime.evaluate', { expression, returnByValue: true })).result.value;
  const check = (condition, message) => { if (!condition) throw new Error(message); };
  await send('Page.enable');
  await send('Emulation.setTouchEmulationEnabled', { enabled: true, maxTouchPoints: 1 });
  await send('Page.navigate', { url: 'http://127.0.0.1:3000/' });
  await wait(800);
  const reports = [];
  for (const { name, width, height } of [{ name: 'portrait', width: 390, height: 844 }, { name: 'landscape', width: 844, height: 390 }]) {
    await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile: true, screenWidth: width, screenHeight: height });
    await wait(100);
    const layout = await evaluate(`(() => {
      const rect = el => { const r = el.getBoundingClientRect(); return { x:r.x, y:r.y, width:r.width, height:r.height, right:r.right, bottom:r.bottom }; };
      const buttons = [...document.querySelectorAll('.touch-controls button')];
      return { viewport:{width:innerWidth,height:innerHeight}, controlsVisible:getComputedStyle(document.querySelector('.touch-controls')).display !== 'none', buttons:buttons.map(b=>({label:b.textContent.trim(),key:b.dataset.key,rect:rect(b)})), canvas:rect(document.querySelector('canvas')), overflow:document.documentElement.scrollWidth > innerWidth || document.documentElement.scrollHeight > innerHeight };
    })()`);
    check(layout.controlsVisible && layout.buttons.length === 5, `${name}: touch controls unavailable`);
    check(layout.buttons.every(b => b.rect.x >= 0 && b.rect.y >= 0 && b.rect.right <= width && b.rect.bottom <= height), `${name}: controls outside viewport`);
    check(!layout.overflow, `${name}: page overflow`);
    const right = layout.buttons.find(button => button.key === 'ArrowRight').rect;
    const x = right.x + right.width / 2, y = right.y + right.height / 2;
    await send('Input.dispatchTouchEvent', { type:'touchStart', touchPoints:[{x,y,id:1}] });
    const movementHeld = await evaluate("keys.has('ArrowRight')");
    await send('Input.dispatchTouchEvent', { type:'touchEnd', touchPoints:[] });
    const movementReleased = !(await evaluate("keys.has('ArrowRight')"));
    const oldPup = await evaluate("document.getElementById('mountName').textContent");
    const swap = layout.buttons.find(button => button.key === 'KeyE').rect;
    await send('Input.dispatchTouchEvent', { type:'touchStart', touchPoints:[{x:swap.x+swap.width/2,y:swap.y+swap.height/2,id:2}] });
    await send('Input.dispatchTouchEvent', { type:'touchEnd', touchPoints:[] });
    const newPup = await evaluate("document.getElementById('mountName').textContent");
    check(movementHeld && movementReleased, `${name}: movement touch input failed`);
    check(oldPup !== newPup, `${name}: pup-switch touch input failed`);
    reports.push({name, viewport:layout.viewport, touchButtons:layout.buttons.length, controlsInBounds:true, movementTouch:'pass', pupSwitchTouch:'pass', noPageOverflow:!layout.overflow});
  }
  console.log(JSON.stringify(reports, null, 2));
  ws.close();
})().catch(error => { console.error(error); process.exitCode = 1; });
