content.text:
Read file game.js, lines 1-416
1: const canvas = document.getElementById('game');
2: const ctx = canvas.getContext('2d');
3: const catchCountEl = document.getElementById('catchCount');
4: const missionTextEl = document.getElementById('missionText');
5: const mountNameEl = document.getElementById('mountName');
6: const gameTitleEl = document.getElementById('gameTitle');
7: const gameEditionEl = document.getElementById('gameEdition');
8: const screenMessage = document.getElementById('screenMessage');
9: const screenTitle = document.getElementById('screenTitle');
10: const screenText = document.getElementById('screenText');
11: 
12: const world = {
13:   width: 1200,
14:   height: 760,
15: };
16: 
17: const keys = new Set();
18: const touchButtons = document.querySelectorAll('[data-key]');
19: 
20: for (const button of touchButtons) {
21:   const key = button.dataset.key;
22:   const setKey = (active) => {
23:     if (active) keys.add(key);
24:     else keys.delete(key);
25:   };
26: 
27:   button.addEventListener('pointerdown', (e) => {
28:     e.preventDefault();
29:     if (key === 'KeyE') {
30:       swapMount();
31:       return;
32:     }
33:     button.setPointerCapture?.(e.pointerId);
34:     setKey(true);
35:   });
36:   button.addEventListener('pointerup', () => setKey(false));
37:   button.addEventListener('pointercancel', () => setKey(false));
38: }
39: 
40: window.addEventListener('keydown', (event) => {
41:   if (event.code === 'KeyE' && !event.repeat) {
42:     event.preventDefault();
43:     swapMount();
44:   }
45:   if (event.code === 'KeyR' && !event.repeat) resetGame();
46:   keys.add(event.code);
47: });
48: 
49: window.addEventListener('keyup', (event) => {
50:   keys.delete(event.code);
51: });
52: 
53: const state = {
54:   time: 0,
55:   stars: 0,
56:   totalStars: 6,
57:   win: false,
58:   phase: 'playing',
59:   noticeTimer: 0,
60:   mounted: 'Bootin’',
61:   mountIndex: 0,
62:   campfire: { x: 1050, y: 640, r: 48 },
63:   player: {
64:     x: 180,
65:     y: 520,
66:     vx: 0,
67:     vy: 0,
68:     radius: 20,
69:     speed: 240,
70:   },
71:   starsList: [
72:     { x: 210, y: 160, r: 12 },
73:     { x: 332, y: 315, r: 12 },
74:     { x: 520, y: 198, r: 12 },
75:     { x: 660, y: 390, r: 12 },
76:     { x: 840, y: 220, r: 12 },
77:     { x: 975, y: 120, r: 12 },
78:   ],
79:   obstacles: [
80:     { x: 260, y: 460, w: 120, h: 170 },
81:     { x: 432, y: 335, w: 180, h: 140 },
82:     { x: 615, y: 500, w: 190, h: 140 },
83:     { x: 845, y: 360, w: 210, h: 160 },
84:   ],
85: };
86: 
87: const mounts = [
88:   { name: 'Bootin’', title: 'Rootin’ Tootin’ Bootin’', edition: 'Black Version · Bootin’s wild west', color: '#f2e7d0', patch: '#a94e31', muzzle: '#e9c9a0', boot: '#a44d30', hat: '#8b452d', trail: 'rgba(255, 194, 103, 0.45)' },
89:   { name: 'Chewy', title: 'What the Hell, Chewy?', edition: 'White Version · Chewy’s wild west', color: '#332522', patch: '#b57850', muzzle: '#b57850', boot: '#c88a4e', hat: '#26201d', trail: 'rgba(139, 211, 255, 0.38)' },
90: ];
91: 
92: function swapMount() {
93:   state.mountIndex = (state.mountIndex + 1) % mounts.length;
94:   const pup = mounts[state.mountIndex];
95:   state.mounted = pup.name;
96:   mountNameEl.textContent = state.mounted;
97:   gameTitleEl.textContent = pup.title;
98:   gameEditionEl.textContent = pup.edition;
99: }
100: 
101: function setMessage(title, text, visible = true, duration = 0) {
102:   screenTitle.textContent = title;
103:   screenText.textContent = text;
104:   state.noticeTimer = duration;
105:   screenMessage.classList.toggle('visible', visible);
106: }
107: 
108: function resetGame() {
109:   state.stars = 0;
110:   state.win = false;
111:   state.phase = 'playing';
112:   state.noticeTimer = 0;
113:   state.player.x = 180;
114:   state.player.y = 520;
115:   state.player.vx = 0;
116:   state.player.vy = 0;
117:   state.mountIndex = 0;
118:   state.starsList = [
119:     { x: 210, y: 160, r: 12 },
120:     { x: 332, y: 315, r: 12 },
121:     { x: 520, y: 198, r: 12 },
122:     { x: 660, y: 390, r: 12 },
123:     { x: 840, y: 220, r: 12 },
124:     { x: 975, y: 120, r: 12 },
125:   ];
126:   state.mounted = mounts[0].name;
127:   starCountEl.textContent = `0 / ${state.totalStars}`;
128:   mountNameEl.textContent = state.mounted;
129:   gameTitleEl.textContent = mounts[0].title;
130:   gameEditionEl.textContent = mounts[0].edition;
131:   setMessage('Welcome to the Frontier', 'Ride through the canyon, gather the legendary sparks, and return to camp before sundown.', false);
132: }
133: 
134: function clamp(value, min, max) {
135:   return Math.min(Math.max(value, min), max);
136: }
137: 
138: function rectCircleCollide(rect, circle) {
139:   const closestX = clamp(circle.x, rect.x, rect.x + rect.w);
140:   const closestY = clamp(circle.y, rect.y, rect.y + rect.h);
141:   const dx = circle.x - closestX;
142:   const dy = circle.y - closestY;
143:   return dx * dx + dy * dy < circle.radius * circle.radius;
144: }
145: 
146: function update(dt) {
147:   if (state.phase === 'ended') return;
148:   if (state.noticeTimer > 0) {
149:     state.noticeTimer -= dt;
150:     if (state.noticeTimer <= 0) screenMessage.classList.remove('visible');
151:   }
152: 
153:   const moveX = (keys.has('ArrowRight') || keys.has('KeyD') ? 1 : 0) - (keys.has('ArrowLeft') || keys.has('KeyA') ? 1 : 0);
154:   const moveY = (keys.has('ArrowDown') || keys.has('KeyS') ? 1 : 0) - (keys.has('ArrowUp') || keys.has('KeyW') ? 1 : 0);
155: 
156:   const length = Math.hypot(moveX, moveY) || 1;
157:   const vx = (moveX / length) * state.player.speed;
158:   const vy = (moveY / length) * state.player.speed;
159: 
160:   let nextX = state.player.x + vx * dt;
161:   let nextY = state.player.y + vy * dt;
162: 
163:   const radius = state.player.radius;
164: 
165:   for (const obstacle of state.obstacles) {
166:     const hit = rectCircleCollide(obstacle, { x: nextX, y: nextY, radius });
167:     if (hit) {
168:       const prevX = state.player.x;
169:       const prevY = state.player.y;
170:       const candidateX = state.player.x + vx * dt;
171:       const candidateY = state.player.y + vy * dt;
172:       const safeX = rectCircleCollide(obstacle, { x: candidateX, y: prevY, radius }) ? state.player.x : candidateX;
173:       const safeY = rectCircleCollide(obstacle, { x: prevX, y: candidateY, radius }) ? state.player.y : candidateY;
174:       nextX = safeX;
175:       nextY = safeY;
176:     }
177:   }
178: 
179:   const previousX = state.player.x;
180:   const previousY = state.player.y;
181:   state.player.x = clamp(nextX, radius + 10, world.width - radius - 10);
182:   state.player.y = clamp(nextY, radius + 10, world.height - radius - 10);
183:   state.player.vx = (state.player.x - previousX) / dt;
184:   state.player.vy = (state.player.y - previousY) / dt;
185: 
186:   for (let i = state.starsList.length - 1; i >= 0; i--) {
187:     const star = state.starsList[i];
188:     const dist = Math.hypot(state.player.x - star.x, state.player.y - star.y);
189:     if (dist < star.r + state.player.radius + 8) {
190:       state.starsList.splice(i, 1);
191:       state.stars += 1;
192:       starCountEl.textContent = `${state.stars} / ${state.totalStars}`;
193:       if (state.stars >= state.totalStars) {
194:         setMessage('Treat trail complete!', 'You found all six golden treats! Bring Bootin’ and Chewy back to the ranch campfire.', true, 2.4);
195:       }
196:     }
197:   }
198: 
199:   const campDist = Math.hypot(state.player.x - state.campfire.x, state.player.y - state.campfire.y);
200:   if (campDist < 58 && state.stars >= state.totalStars && !state.win) {
201:     state.win = true;
202:     state.phase = 'ended';
203:     setMessage('Good dogs. Great legends.', 'Bootin’ and Chewy saved the ranch! Press R to run the trail again, or E to switch editions.', true);
204:   }
205: 
206:   if (campDist < 58 && state.stars < state.totalStars) {
207:     const treatsLeft = state.totalStars - state.stars;
208:     setMessage('Campfire ahead', `You still need ${treatsLeft} golden treat${treatsLeft === 1 ? '' : 's'}. Sniff out the rest!`, true, 1.8);
209:   }
210: }
211: 
212: function drawBackground() {
213:   const sky = ctx.createLinearGradient(0, 0, 0, world.height);
214:   sky.addColorStop(0, '#8eb495');
215:   sky.addColorStop(0.42, '#e4cb89');
216:   sky.addColorStop(0.7, '#c98856');
217:   sky.addColorStop(1, '#744638');
218:   ctx.fillStyle = sky;
219:   ctx.fillRect(0, 0, world.width, world.height);
220: 
221:   // Distant mesas and warm afternoon sun.
222:   ctx.fillStyle = '#f6d991';
223:   ctx.beginPath();
224:   ctx.arc(1030, 105, 54, 0, Math.PI * 2);
225:   ctx.fill();
226:   ctx.fillStyle = '#9b6b50';
227:   ctx.beginPath();
228:   ctx.moveTo(0, 320); ctx.lineTo(110, 210); ctx.lineTo(186, 212); ctx.lineTo(270, 320);
229:   ctx.lineTo(360, 185); ctx.lineTo(450, 185); ctx.lineTo(540, 320);
230:   ctx.lineTo(650, 235); ctx.lineTo(760, 235); ctx.lineTo(875, 320);
